const DIAMETER_TOLERANCE = 0.0015;

export function bulletById(id: string): Bullet | undefined {
  return bullets.find((bullet) => bullet.id === id);
}

export function bulletsForDiameter(diameterIn: number): Bullet[] {
  return bullets.filter((bullet) => Math.abs(bullet.diameterIn - diameterIn) <= DIAMETER_TOLERANCE);
}

export function bulletBrands(pool: Bullet[], type: string): string[] {
  const names = new Set<string>();
  for (const bullet of pool) {
    if (!type || bullet.type === type) names.add(bullet.brand);
  }
  return [...names].sort((a, b) => a.localeCompare(b));
}

export function bulletTypes(pool: Bullet[], brand: string): string[] {
  const names = new Set<string>();
  for (const bullet of pool) {
    if (!brand || bullet.brand === brand) names.add(bullet.type);
  }
  return [...names].sort((a, b) => a.localeCompare(b));
}

export function bulletProducts(pool: Bullet[], brand: string, type: string): Bullet[] {
  return pool
    .filter((bullet) => bullet.brand === brand && (!type || bullet.type === type))
    .sort((a, b) => a.weightGr - b.weightGr || a.name.localeCompare(b.name));
}

export function reconcileBulletChoice(
  diameterIn: number | null,
  brand: string,
  type: string,
  id: string,
): { bulletBrand: string; bulletType: string; bulletId: string } {
  if (diameterIn == null) return { bulletBrand: "", bulletType: "", bulletId: "" };
  const pool = bulletsForDiameter(diameterIn);
  let nextBrand = brand;
  let nextType = type;
  if (nextBrand && !pool.some((bullet) => bullet.brand === nextBrand)) nextBrand = "";
  if (
    nextType &&
    !pool.some((bullet) => bullet.type === nextType && (!nextBrand || bullet.brand === nextBrand))
  ) {
    nextType = "";
  }
  let nextId = id;
  if (nextId) {
    const bullet = bulletById(nextId);
    const listed = bullet != null && pool.some((item) => item.id === nextId);
    if (
      !bullet ||
      !listed ||
      (nextBrand && bullet.brand !== nextBrand) ||
      (nextType && bullet.type !== nextType)
    ) {
      nextId = "";
    }
  }
  return { bulletBrand: nextBrand, bulletType: nextType, bulletId: nextId };
}
